CREATE OR REPLACE FUNCTION private.check_daily_table_conflicts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  selected_ids text[];
  selected_physical_ids text[];
  occupied_groups text[];
  start_at timestamptz;
begin
  if tg_op = 'UPDATE' then
    if new.booking_date is not distinct from old.booking_date
       and new.booking_time is not distinct from old.booking_time
       and new.tables is not distinct from old.tables
       and new.booking_type is not distinct from old.booking_type
       and new.status is not distinct from old.status then return new; end if;
  end if;
  if new.status in ('cancelled', 'no_show') then return new; end if;
  if coalesce(btrim(new.tables), '') = '' then return new; end if;
  start_at := private.booking_scheduled_at(new.booking_date, new.booking_time);
  if start_at is null then
    raise exception 'Data e ora valide obbligatorie per assegnare tavoli' using errcode = '22023';
  end if;
  select array_agg(btrim(t)) into selected_ids from unnest(string_to_array(new.tables, ',')) t;
  if exists (select 1 from unnest(selected_ids) t where t not in
    ('10+11','12','13+14','15+16+17','15+16','17','18+19','18','19','20+21','22','23')) then
    raise exception 'Configurazione tavolo non valida' using errcode = '22023';
  end if;
  if cardinality(selected_ids) <> (select count(distinct t) from unnest(selected_ids) t) then
    raise exception 'Lo stesso tavolo non può essere indicato due volte' using errcode = '22023';
  end if;
  select array_agg(btrim(physical_id)) into selected_physical_ids
    from unnest(selected_ids) grouped_id
    cross join lateral unnest(string_to_array(grouped_id, '+')) physical_id;
  if cardinality(selected_physical_ids) <> (select count(distinct t) from unnest(selected_physical_ids) t) then
    raise exception 'Lo stesso tavolo fisico non può essere indicato in gruppi diversi' using errcode = '22023';
  end if;
  if exists (
    select 1 from public.bookings b
    cross join lateral unnest(string_to_array(coalesce(b.tables, ''), ',')) t
    cross join lateral unnest(string_to_array(btrim(t), '+')) physical_id
    where b.id <> new.id and b.status not in ('cancelled','no_show')
      and private.booking_intervals_overlap(new.booking_date,new.booking_time,b.booking_date,b.booking_time)
      and btrim(physical_id) = any(selected_physical_ids)
  ) then
    raise exception 'Tavolo già assegnato a un’altra prenotazione nella stessa giornata' using errcode = '23505';
  end if;
  -- Lo staff può scegliere qualsiasi unità libera: la configurazione è un consiglio.
  if coalesce(auth.jwt()->'app_metadata'->>'role','')='admin' then return new; end if;
  -- Gli assegnati restano in uso per la giornata, senza scadenza temporale.
    select array_agg(distinct grouped_id) into occupied_groups from (
      select btrim(t) as grouped_id from unnest(selected_ids) t
      union all
      select btrim(t) from public.bookings b
      cross join lateral unnest(string_to_array(coalesce(b.tables,''),',')) t
      where b.id <> new.id and b.status not in ('cancelled','no_show')
        and private.booking_intervals_overlap(new.booking_date,new.booking_time,b.booking_date,b.booking_time)

    ) occupied where grouped_id in ('15+16+17','15+16','17','18+19','18','19');
    if occupied_groups is not null and not (
      occupied_groups <@ array['15+16+17','18+19']::text[]
      or occupied_groups <@ array['15+16','17','18+19']::text[]
      or occupied_groups <@ array['15+16','17','18','19']::text[]
    ) then
      raise exception 'Configurazione dei tavoli 15-19 non valida' using errcode = '22023';
    end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.online_day_status(day text, people integer, exclude_id bigint DEFAULT NULL::bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare row_data record; selected_group text; physical text[];
  used text[] := array[]::text[]; groups text[] := array[]::text[];
  residual jsonb; point_time text;
  parties integer[] := case when people=0 then array[]::integer[] else array[people] end; covers integer;
begin
  if people is null or people not between 0 and 6 then return 'unverified'; end if;
  if people > 0 and exists(select 1 from public.online_booking_closures c where c.booking_date = day::date) then return 'closed'; end if;
  select coalesce(sum(b.party_size),0) into covers from public.bookings b
    where b.booking_date=day and b.status='confirmed' and (exclude_id is null or b.id<>exclude_id);
  if covers + people > 25 then return 'full'; end if;
  -- Il controllo pubblico giorno/persone resta prudente, ma conta unità intere.
  for point_time in select distinct b.booking_time from public.bookings b
      where b.booking_date=day and b.status not in ('cancelled','no_show')
        and (exclude_id is null or b.id<>exclude_id) loop
    residual:=private.service_capacity(day,point_time,exclude_id);
    if not (residual->>'verified')::boolean then return 'unverified'; end if;
    if (residual->>'remaining')::integer<people then return 'full'; end if;
  end loop;
  for row_data in select b.* from public.bookings b where b.booking_date=day
      and b.status not in ('cancelled','no_show') and coalesce(b.booking_type,'normale')='normale'
      and (exclude_id is null or b.id<>exclude_id) order by b.id loop
    if row_data.party_size is null or row_data.party_size < 1 then return 'unverified'; end if;
    if coalesce(btrim(row_data.tables),'') = '' then
      parties := parties || row_data.party_size;
    else
      foreach selected_group in array string_to_array(row_data.tables,',') loop
        selected_group := btrim(selected_group);
        if not exists(select 1 from private.online_table_groups() g where g.group_id=selected_group) then return 'unverified'; end if;
        physical := string_to_array(selected_group,'+');
        if exists(select 1 from public.bookings other
          where other.id<row_data.id and other.booking_date=day
            and other.status not in ('cancelled','no_show')
            and (exclude_id is null or other.id<>exclude_id)
            and private.booking_intervals_overlap(row_data.booking_date,row_data.booking_time,other.booking_date,other.booking_time)
            and exists(select 1 from unnest(string_to_array(coalesce(other.tables,''),',')) t
              cross join lateral unnest(string_to_array(btrim(t),'+')) id where btrim(id)=any(physical))) then return 'unverified'; end if;
        used := used || physical; groups := groups || selected_group;
      end loop;
    end if;
  end loop;
  -- Le configurazioni sono preferenze: i tavoli occupati restano indisponibili.
  select coalesce(array_agg(p order by p desc),array[]::integer[]) into parties from unnest(parties) p;
  return case when private.fit_online_parties(parties,used,groups) then 'available' else 'full' end;
end;
$function$

CREATE OR REPLACE FUNCTION private.prepare_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  administrator boolean := coalesce(auth.jwt()->'app_metadata'->>'role' = 'admin',false);
  customer boolean := current_setting('role',true) = 'authenticated' and not administrator;
  dt timestamptz;
begin
  if new.source='staff' then new.source := 'agenda'; end if;
  if new.source='ai' then new.source := 'booking'; end if;

  if customer then
    if new.source <> 'booking' or new.user_id is distinct from auth.uid() then
      raise exception 'Record non autorizzato' using errcode='42501';
    end if;

    if tg_op='INSERT' then
      new.status := 'confirmed';
      new.tables := '';
      new.reminder_status := 'skipped';
      new.reminder_attempts := 0;
      new.created_at := now();
      new.consenso_ricordami := false;
      new.consenso_data := null;
      new.arrived_at := null;
      new.marketing_visit_counted_at := null;
    else
      if (to_jsonb(new) - array[
        'name','email','phone','booking_date','booking_time',
        'party_size','notes','status','updated_at'
      ]) is distinct from
         (to_jsonb(old) - array[
        'name','email','phone','booking_date','booking_time',
        'party_size','notes','status','updated_at'
      ]) then
        raise exception 'Campo riservato all’amministratore' using errcode='42501';
      end if;

      if old.status='cancelled' and new.status <> old.status then
        raise exception 'Prenotazione annullata';
      end if;
    end if;
  end if;

  if tg_op='INSERT' and new.source='booking' then
    if new.privacy_accepted_at is null
       or new.privacy_version is distinct from '2026-10-04-online-v1' then
      raise exception 'Lettura informativa privacy obbligatoria'
        using errcode='22023';
    end if;

    new.status := 'confirmed';
    new.tables := '';
    new.reminder_status := 'skipped';
    new.booking_type := 'normale';
    new.consenso_ricordami := false;
    new.consenso_data := null;
  end if;

  new.updated_at := now();

  -- LIMITE 25: SOLO PRENOTAZIONI DEL SITO.
  -- Nel conteggio vengono comunque considerate TUTTE le prenotazioni
  -- confirmed (anche quelle inserite manualmente dall'Agenda).
  if new.source='booking'
     and new.status='confirmed'
     and (
       tg_op='INSERT'
       or old.status is distinct from new.status
       or new.booking_date is distinct from old.booking_date
       or new.party_size is distinct from old.party_size
     ) then

    perform pg_advisory_xact_lock(734512);

    if (
      select coalesce(sum(b.party_size),0)
      from public.bookings b
      where b.id<>new.id
        and b.status='confirmed'
        and b.booking_date=new.booking_date
    ) + new.party_size > 25 then
      raise exception 'Limite giornaliero di 25 coperti raggiunto'
        using errcode='P0001';
    end if;
  end if;

  -- CONTROLLI PRENOTAZIONE PUBBLICA
  if new.source='booking'
     and new.status='confirmed'
     and (
       tg_op='INSERT'
       or new.booking_date is distinct from old.booking_date
       or new.booking_time is distinct from old.booking_time
       or new.party_size is distinct from old.party_size
     ) then

    perform pg_advisory_xact_lock(734512);

    if new.booking_date !~ '^\d{4}-\d{2}-\d{2}$'
       or new.booking_time !~ '^(18|19|20|21|22):(00|30)$|^23:00$' then
      raise exception 'Data o ora non valide';
    end if;

    dt := (new.booking_date || ' ' || new.booking_time)::timestamp
          at time zone 'Europe/Rome';

    if extract(isodow from new.booking_date::date)=1
       or dt < now()+interval '30 minutes'
       or new.booking_date::date >
          (now() at time zone 'Europe/Rome')::date+60
       or new.party_size not between 1 and 6 then
      raise exception 'Data o coperti non disponibili';
    end if;

    if length(btrim(new.name)) not between 2 and 60
       or length(new.notes)>300
       or new.phone !~ '^\+[1-9][0-9]{7,14}$'
       or length(new.email)>120 then
      raise exception 'Contatti non validi';
    end if;

    if (
      select count(*)
      from public.bookings b
      where b.id<>new.id
        and b.status='confirmed'
        and regexp_replace(b.phone,'[^0-9]','','g')
            = regexp_replace(new.phone,'[^0-9]','','g')
        and (b.booking_date || ' ' || b.booking_time)::timestamp
            at time zone 'Europe/Rome' > now()
    ) >= 2 then
      raise exception 'Limite prenotazioni per telefono raggiunto';
    end if;

    if private.online_day_status(
         new.booking_date,
         new.party_size,
         new.id
       ) <> 'available' then
      raise exception
        'Disponibilità cambiata: aggiorna il calendario o contatta il locale'
        using errcode='P0001';
    end if;

    if tg_op='INSERT' then
      new.tables := '';
    end if;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.process_booking_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  b public.bookings%rowtype;
  field_name text;
  changes jsonb;
  day_value date;
begin
  if coalesce(auth.jwt()->'app_metadata'->>'role','') <> 'admin' then
    raise exception 'Accesso riservato allo staff' using errcode = '42501';
  end if;
  -- Stesso ordine di lock della logica modifica: serializza le approvazioni.
  perform pg_advisory_xact_lock(734512);
  select * into b from public.bookings where id = new.booking_id for update;
  if not found then raise exception 'Prenotazione non trovata' using errcode = 'P0002'; end if;
  if tg_op = 'INSERT' then
    if coalesce(b.status,'confirmed') <> 'confirmed' then raise exception 'Prenotazione non più modificabile'; end if;
    if new.request_type = 'cancellazione' then
      if new.requested_value is not null and new.requested_value <> 'null'::jsonb then raise exception 'Cancellazione senza valore'; end if;
      new.requested_value := null;
    elsif new.request_type = 'persone' then
      if jsonb_typeof(new.requested_value) is distinct from 'number' or new.requested_value::text !~ '^[1-6]$' then raise exception 'Numero persone non valido'; end if;
    elsif new.request_type in ('data','ora','note') then
      if jsonb_typeof(new.requested_value) is distinct from 'string' then raise exception 'Valore non valido'; end if;
      if new.request_type = 'data' then
        if new.requested_value #>> '{}' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Data non valida'; end if;
        day_value := (new.requested_value #>> '{}')::date;
        if to_char(day_value,'YYYY-MM-DD') <> new.requested_value #>> '{}' then raise exception 'Data non valida'; end if;
      elsif new.request_type = 'ora' and new.requested_value #>> '{}' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'Ora non valida';
      elsif new.request_type = 'note' and length(new.requested_value #>> '{}') > 300 then raise exception 'Note troppo lunghe'; end if;
    else raise exception 'Tipo richiesta non valido'; end if;
    new.expected := jsonb_build_object('booking_date',b.booking_date,'booking_time',b.booking_time,'party_size',b.party_size,'tables',b.tables,'notes',b.notes,'status',b.status);
    new.status := 'pending'; new.created_at := now(); new.created_by := auth.uid();
    new.reviewed_at := null; new.reviewed_by := null;
  else
    if old.status <> 'pending' or new.status not in ('approved','rejected') then raise exception 'Richiesta già gestita o decisione non valida' using errcode = '40001'; end if;
    if (to_jsonb(new) - array['status','reviewed_at','reviewed_by']) is distinct from
       (to_jsonb(old) - array['status','reviewed_at','reviewed_by']) then raise exception 'Richiesta immutabile'; end if;
    if new.status = 'approved' then
      if jsonb_build_object('booking_date',b.booking_date,'booking_time',b.booking_time,'party_size',b.party_size,'tables',b.tables,'notes',b.notes,'status',b.status) is distinct from old.expected then
        raise exception 'Prenotazione cambiata: rifiuta la richiesta e registrane una aggiornata' using errcode = '40001';
      end if;
      if coalesce(b.status,'confirmed') <> 'confirmed' then raise exception 'Prenotazione non più modificabile'; end if;
      if old.request_type = 'cancellazione' then
        perform public.admin_set_booking_status_with_history(old.booking_id,'cancelled');
      else
        field_name := case old.request_type when 'data' then 'booking_date' when 'ora' then 'booking_time' when 'persone' then 'party_size' when 'note' then 'notes' end;
        changes := jsonb_build_object(field_name,old.requested_value);
        perform public.admin_update_booking(old.booking_id,changes,old.expected - 'status');
      end if;
    end if;
    new.reviewed_at := now(); new.reviewed_by := auth.uid();
  end if;
  insert into public.booking_history(booking_id,action,old_data,new_data)
    values(new.booking_id, 'customer_request_' || case when tg_op = 'INSERT' then 'created' else new.status end,
      case when tg_op = 'INSERT' then '{}'::jsonb else jsonb_build_object('request_status',old.status) end,
      jsonb_build_object('request_id',new.id,'request_type',new.request_type,'requested_value',new.requested_value,
        'request_status',new.status,'actor_id',auth.uid()));
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.protect_pending_online_bookings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
      begin
        if new.status in ('cancelled','no_show') then return new; end if;
        if tg_op='UPDATE' then
          if new.booking_date is not distinct from old.booking_date
             and new.booking_time is not distinct from old.booking_time
             and new.party_size is not distinct from old.party_size
             and new.tables is not distinct from old.tables
             and new.booking_type is not distinct from old.booking_type
             and (new.status is not distinct from old.status or old.status not in ('cancelled','no_show')) then return new; end if;
        end if;
        -- Assegnazione manuale ADMIN: la tutela dei pendenti è una raccomandazione.
        if coalesce(auth.jwt()->'app_metadata'->>'role','')='admin' then
          if tg_op='INSERT' and coalesce(btrim(new.tables),'')<>'' then return new; end if;
          if tg_op='UPDATE' and new.tables is distinct from old.tables then return new; end if;
        end if;
        -- Lock, trigger e ricerca di capienza esistenti restano invariati.
        if exists(select 1 from public.bookings b where b.source='booking'
          and b.status not in ('cancelled','no_show') and coalesce(btrim(b.tables),'')=''
          and private.booking_intervals_overlap(new.booking_date,new.booking_time,b.booking_date,b.booking_time))
          and not private.pending_online_windows_fit(new.booking_date) then
          raise exception 'Assegnazione non salvata: non resterebbe posto per le prenotazioni online già confermate senza tavolo'
            using errcode='23514';
        end if;
        return new;
      end;
      $function$

CREATE OR REPLACE FUNCTION private.queue_booking_lifecycle_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.booking_communications%rowtype; k text;
begin
 if tg_op='INSERT' then
  if coalesce(new.status,'confirmed')='confirmed' then perform private.queue_booking_email(new,'confirmation','created:'||new.id); end if;
 elsif old.status is distinct from new.status
    or private.booking_email_snapshot(old) is distinct from private.booking_email_snapshot(new)
    or old.email is distinct from new.email then
  -- La prenotazione è già bloccata dall'UPDATE: prima booking, poi comunicazioni.
  -- Mantiene accepted/unknown/sending come esiti storici, senza inventare un esito.
  for c in update public.booking_communications set status='superseded',error_code='booking_changed'
      where booking_id=new.id and channel='email' and status in ('queued','failed','skipped') returning * loop
   insert into public.booking_communication_logs(communication_id,status,error_code) values(c.id,'superseded','booking_changed');
  end loop;
  if new.status in ('confirmed','cancelled') then
   k := case when new.status='cancelled' then 'cancelled'
             when old.status is distinct from new.status then 'confirmation' else 'updated' end;
   perform private.queue_booking_email(new,k,'changed:'||new.id||':'||gen_random_uuid());
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.record_admin_booking_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  previous_values jsonb;
  current_values jsonb;
  previous_changes jsonb := '{}'::jsonb;
  current_changes jsonb := '{}'::jsonb;
  field_name text;
begin
  if coalesce(auth.jwt()->'app_metadata'->>'role', '') <> 'admin' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    insert into public.booking_history (booking_id, action, old_data, new_data, actor_id)
      values (new.id, 'booking_created', '{}'::jsonb,
        jsonb_build_object('booking_date', new.booking_date, 'booking_time', new.booking_time,
          'party_size', new.party_size, 'tables', new.tables, 'status', new.status,
          'booking_type', new.booking_type), auth.uid());
    return new;
  end if;

  previous_values := jsonb_build_object(
    'status', old.status, 'booking_date', old.booking_date,
    'booking_time', old.booking_time, 'party_size', old.party_size,
    'tables', old.tables, 'notes', old.notes
  );
  current_values := jsonb_build_object(
    'status', new.status, 'booking_date', new.booking_date,
    'booking_time', new.booking_time, 'party_size', new.party_size,
    'tables', new.tables, 'notes', new.notes
  );
  foreach field_name in array array[
    'status', 'booking_date', 'booking_time', 'party_size', 'tables', 'notes'
  ] loop
    if previous_values->field_name is distinct from current_values->field_name then
      previous_changes := previous_changes || jsonb_build_object(field_name, previous_values->field_name);
      current_changes := current_changes || jsonb_build_object(field_name, current_values->field_name);
    end if;
  end loop;
  if previous_changes = '{}'::jsonb then return new; end if;

  insert into public.booking_history (booking_id, action, old_data, new_data, actor_id)
    values (new.id,
      case when previous_changes = jsonb_build_object('status', previous_values->'status')
        then 'status_changed' else 'booking_updated' end,
      previous_changes, current_changes, auth.uid());
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_manual_no_show()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  scheduled_at timestamptz;
begin
  if old.status in ('cancelled', 'completed') then
    raise exception 'Una prenotazione cancellata o completata non può diventare No-show'
      using errcode = '22023';
  end if;

  if new.booking_date is null
     or new.booking_time is null
     or new.booking_date !~ '^[1-9][0-9]{3}-[0-9]{2}-[0-9]{2}$'
     or new.booking_time !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$' then
    raise exception 'Data o orario non validi: impossibile verificare i 30 minuti'
      using errcode = '22023';
  end if;

  begin
    scheduled_at :=
      (new.booking_date || ' ' || new.booking_time)::timestamp
      at time zone 'Europe/Rome';
  exception
    when invalid_datetime_format or datetime_field_overflow then
      raise exception 'Data o orario non validi: impossibile verificare i 30 minuti'
        using errcode = '22023';
  end;

  if clock_timestamp() < scheduled_at + interval '30 minutes' then
    raise exception 'No-show non consentito: devono essere trascorsi almeno 30 minuti dall’orario previsto della prenotazione (Europe/Rome)'
      using errcode = '22023';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_assign_booking_tables(booking_id bigint, changes jsonb, expected jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  previous_booking public.bookings%rowtype;
  saved_booking public.bookings%rowtype;
  previous_values jsonb;
  key_name text;
  selected_tables text;
  selected_party_size integer;
  selected_count integer;
  selected_capacity integer;
  availability_change boolean;
  date_value date;
  selected_date date;
  selected_time text;
begin
  if coalesce(auth.jwt()->'app_metadata'->>'role', '') <> 'admin' then
    raise exception 'Accesso riservato all’amministratore' using errcode = '42501';
  end if;
