CREATE OR REPLACE FUNCTION public.admin_set_booking_status(booking_id bigint, booking_status text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  current_status text;
  saved_status text;
begin
  if coalesce(auth.jwt()->'app_metadata'->>'role', '') <> 'admin' then
    raise exception 'Accesso riservato all’amministratore'
      using errcode = '42501';
  end if;

  if booking_status is null or booking_status not in (
    'confirmed',
    'arrived',
    'completed',
    'cancelled',
    'no_show'
  ) then
    raise exception 'Stato non valido'
      using errcode = '22023';
  end if;

  if booking_status = 'no_show' then
    select b.status
    into current_status
    from public.bookings b
    where b.id = booking_id
    for update;

    if not found then
      raise exception 'Prenotazione non trovata o non accessibile'
        using errcode = 'P0002';
    end if;

    if current_status = 'no_show' then
      return current_status;
    end if;
  end if;

  update public.bookings as b
  set status = booking_status
  where b.id = booking_id
  returning b.status into saved_status;

  if not found then
    raise exception 'Prenotazione non trovata o non accessibile'
      using errcode = 'P0002';
  end if;

  return saved_status;
end;
$function$

