CREATE OR REPLACE FUNCTION private.enforce_daily_booking_capacity_25()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  booked_seats integer;
begin
  if new.status <> 'confirmed' then
    return new;
  end if;

  -- Lo staff può superare la capienza pubblica.
  if new.source <> 'booking' then
    return new;
  end if;

  perform pg_advisory_xact_lock(734512);

  select coalesce(sum(b.party_size),0)
  into booked_seats
  from public.bookings b
  where b.booking_date = new.booking_date
    and b.status = 'confirmed'
    and b.id <> new.id;

  if booked_seats + new.party_size > 25 then
    raise exception
      'Capienza massima di 25 coperti raggiunta per la giornata'
      using errcode='23514';
  end if;

  return new;
end;
$function$

